// Which exercises the on-device engine checks today. The list is generated by the coverage audit in
// ZeroToHeroKitTests (RUNNABLE_JSON) and shipped as a resource. Anything not on it opens as an Xcode lab, so a correct
// answer is never silently marked wrong and no lesson shows a Run button that cannot work.
import Foundation

enum DeviceSupport {
    static let runnable: Set<String> = load()

    static func isRunnable(_ id: String) -> Bool { runnable.contains(id) }

    private static func load() -> Set<String> {
        struct Payload: Decodable { let runnable: [String] }
        var urls: [URL] = []
        if let bundled = Bundle.main.url(forResource: "device-support", withExtension: "json") { urls.append(bundled) }
        for url in urls {
            if let data = try? Data(contentsOf: url), let payload = try? JSONDecoder().decode(Payload.self, from: data) {
                return Set(payload.runnable)
            }
        }
        return []
    }
}
